from h import build
R=[
(3712518,"Mélange de base de bœuf haché et de lentilles",
"Ce mélange de bœuf et de lentilles est non seulement plus économique que sa version à la viande seulement, il est aussi plus sain.",
"5 portions (chaque portion pour deux personnes)",None,
["625 g de bœuf haché","2 gros oignons, pelés et finement hachés","250 g de lentilles corail","2 cuillères à soupe de concentré de tomate","1 cube de bouillon de bœuf ou de légumes à faible teneur en sel","800 ml d'eau bouillante","2 cuillères à café d'huile végétale"],
["Faites chauffer une grande poêle antiadhésive à feu moyen et ajoutez l'huile végétale. Ajoutez les oignons hachés et faites cuire 6 à 8 minutes jusqu'à ce qu'ils soient tendres.","Ajoutez les lentilles, le bouillon et le concentré de tomate au mélange de viande hachée et d'oignon. Portez à ébullition, puis réduisez le feu et laissez mijoter 25 minutes à feu doux.","Une fois cuit, divisez le mélange de viande hachée et de lentilles en 5 portions à utiliser."],
[["Note du chef","Une fois préparée, cette recette polyvalente peut servir de base pour des garnitures de tourtes, des caris, des sautés ou des sauces pour pâtes."],["Glucides","Les lentilles sont la principale source de glucides de ce plat. Les valeurs sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Remplacer une partie du bœuf haché par des lentilles a aidé à réduire la teneur en phosphate, mais vous devriez tout de même prendre un chélateur du phosphate avec ce plat si on vous en a prescrit un."],["Protéines","Le bœuf et les lentilles sont les principales sources de protéines de ce plat. Ce plat est une bonne source de protéines et convient donc à une personne qui a besoin d'un régime plus riche en protéines."],["Conservation","La cuisine en lots peut faire économiser de l'argent ainsi que du temps, car de nombreux aliments sont plus avantageux au supermarché lorsqu'ils sont achetés en plus grandes quantités. Les portions de ce mélange peuvent être conservées au réfrigérateur 2 jours ou congelées, en portions simples ou doubles, jusqu'à 3 mois. Décongelez complètement avant de l'utiliser."]],
[]),
(3763636,"Gâteau aux carottes fait de pain rassis",
"Ce gâteau utilise délicieusement le pain rassis pour une gâterie gourmande et faible en potassium.",
"10",None,
[["Gâteau aux carottes","400 g de pain (blanc ou de blé entier), déchiré"],["Gâteau aux carottes","100 g de cassonade claire molle"],["Gâteau aux carottes","1 œuf"],["Gâteau aux carottes","100 g de yogourt entier"],["Gâteau aux carottes","50 g d'huile végétale"],["Gâteau aux carottes","2 cuillères à café de cannelle moulue"],["Gâteau aux carottes","1 cuillère à café de bicarbonate de soude"],["Gâteau aux carottes","1 cuillère à café d'extrait de vanille"],["Gâteau aux carottes","Zeste de 1 orange"],["Gâteau aux carottes","90 g de carotte, râpée"],["Gâteau aux carottes","90 g de raisins secs"],["Crème de fruit de la passion","1 jaune d'œuf"],["Crème de fruit de la passion","1 cuillère à soupe de sucre extra-fin"],["Crème de fruit de la passion","100 g de jus de fruit de la passion"],["Crème de fruit de la passion","15 g de beurre non salé"],["Crème de fruit de la passion","1 cuillère à soupe de fécule de maïs"],["Crème au mascarpone","100 g de crème épaisse"],["Crème au mascarpone","100 g de mascarpone, ramolli"],["Crème au mascarpone","25 g de sucre glace"],["Crème au mascarpone","1 cuillère à café d'essence de vanille"],["Pour servir","½ cuillère à café de cannelle"],["Pour servir","1 cuillère à café de fines lamelles de zeste d'orange"]],
["Préchauffez le four à 175 °C / 145 °C chaleur tournante / thermostat gaz 4 et graissez et farinez une plaque de cuisson rectangulaire de 11 po x 8.5 po. Mettez le pain déchiré dans un robot culinaire et mixez en miettes fines. Ajoutez le sucre, l'œuf, le yogourt, l'huile, la cannelle moulue, le bicarbonate de soude et l'extrait de vanille et mixez jusqu'à consistance lisse. Versez dans un bol à mélanger et incorporez le zeste d'orange, la carotte et les raisins secs jusqu'à ce que le tout soit uniformément mélangé. Mettez la pâte à gâteau dans la plaque de cuisson et faites cuire 25 à 30 minutes, jusqu'à ce qu'une brochette en ressorte propre.","Crème de fruit de la passion : fouettez le jaune d'œuf et le sucre ensemble et mettez de côté dans un bol. Dans une casserole à fond épais, chauffez doucement le jus de fruit de la passion et le beurre juste assez pour faire fondre le beurre, puis incorporez graduellement la fécule de maïs en mélangeant continuellement pour éviter les grumeaux. Retirez le mélange du feu et fouettez-en quelques cuillères à soupe dans le mélange d'œuf dans le bol. Continuez à fouetter, en ajoutant quelques cuillères à soupe du mélange à la fois au mélange d'œuf.","Une fois les deux mélanges bien combinés, versez-les de nouveau dans la casserole et remettez sur un feu doux à moyen, en remuant continuellement pour que les œufs ne caillent pas et ne brouillent pas. Faites cuire 5 à 8 minutes jusqu'à ce que la crème ait épaissi. Retirez du feu et passez au tamis fin dans un bol. Couvrez de pellicule plastique directement sur la surface de la crème et réfrigérez au moins 2 heures avant de l'utiliser.","Lorsque le gâteau est cuit et qu'une brochette en ressort propre, sortez-le du four et laissez refroidir 10 minutes avant de le transférer sur une grille pour poursuivre le refroidissement.","Crème au mascarpone : dans un bol à mélanger, battez le mascarpone et la crème épaisse jusqu'à consistance lisse et crémeuse. Ajoutez graduellement le sucre glace et l'extrait de vanille et continuez à battre jusqu'à ce que le tout soit bien mélangé.","Une fois le gâteau refroidi, coupez-le en 20 carrés. Dressez la crème à la poche sur le pourtour de 10 carrés de gâteau et garnissez le centre d'un peu de crème de fruit de la passion. Placez les 10 carrés restants dessus et décorez avec le reste de la crème. Saupoudrez de cannelle et de zeste d'orange pour terminer. Laissez reposer les gâteaux toute la nuit dans un endroit frais ou même au réfrigérateur, afin que les saveurs se développent."],
[["Note du chef","Un gâteau aux carottes délicieusement moelleux avec un glaçage au fromage à la crème et une crème de fruit de la passion. Bon appétit !"],["Glucides","Le pain est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium si vous respectez les quantités et les tailles de portion indiquées; c'est donc une gâterie appropriée pour les personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation.\nCette recette est riche en phosphate; savourez-la donc comme gâterie occasionnelle et, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est faible en protéines; elle convient donc comme gâterie occasionnelle si on vous a conseillé de manger moins de protéines."],["Option plus économique","Il peut être difficile de se procurer du jus de fruit de la passion. Envisagez plutôt de la mangue ou de l'ananas (ceux-ci sont plus faibles en potassium que le jus de pomme ou d'orange)."],["Sans gluten","Utilisez du pain sans gluten"],["Option plus saine","Cette recette est riche en matières grasses et contient une quantité modérée de sel provenant du bicarbonate; elle ne doit être savourée qu'occasionnellement, dans le cadre d'une alimentation saine et équilibrée."],["Conservation","Une fois cuite et refroidie, cette recette peut être conservée dans un contenant hermétique au réfrigérateur jusqu'à 3 jours."]],
[]),
(3765080,"Salade de poulet et d'orange",
"Un repas léger, faible en calories et en potassium, mais rempli de saveurs intéressantes.",
"4",None,
["1 cuillère à café d'huile d'olive","200 g de poitrine de poulet, coupée en bouchées","1 boîte de 215 g de pois chiches (130 g égouttés) ou 150 g d'edamames","400 g de nouilles de riz","2 laitues Little Gem","2 oranges, pelées et séparées en suprêmes","2 limes, zestées",["Vinaigrette à l'huile de sésame","1 cuillère à soupe d'huile de sésame"],["Vinaigrette à l'huile de sésame","Jus des 2 limes"],["Vinaigrette à l'huile de sésame","1 cuillère à soupe de sauce soja à teneur réduite en sel"],["Vinaigrette à l'huile de sésame","1 cuillère à café de graines de sésame, grillées"]],
["Faites chauffer l'huile dans une poêle peu profonde et faites sauter les morceaux de poulet à feu moyen. Lorsqu'ils sont presque cuits, ajoutez les pois chiches et faites cuire jusqu'à ce qu'ils soient chauds et croustillants. Une fois le poulet bien cuit, retirez-le et égouttez-le sur du papier absorbant pour éliminer l'excès d'huile (si vous utilisez des edamames, ajoutez-les plus tard).","Pendant la cuisson du poulet, faites cuire les nouilles de riz selon les instructions sur l'emballage, puis égouttez. Pour la vinaigrette, fouettez tous les ingrédients jusqu'à ce qu'ils soient bien mélangés et mettez de côté jusqu'au moment de l'utiliser.","Séparez les feuilles de laitue, en déchirant en deux les plus grandes. Mélangez la laitue avec les nouilles, les suprêmes d'orange, le zeste de lime et les edamames (si vous les utilisez à la place des pois chiches).","Incorporez le poulet et les pois chiches à la salade et répartissez dans quatre bols. Assaisonnez chaque portion de vinaigrette à l'huile de sésame, puis servez."],
[["Note du chef","Une recette rapide et facile pour un repas léger et sain."],["Glucides","Les nouilles de riz sont la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium, malgré l'utilisation d'oranges fraîches et de salade. C'est parce que les quantités ont été réduites au minimum; veillez donc à respecter les quantités de tous les ingrédients et les tailles de portion.\nCette recette est riche en phosphate, fourni par le poulet et les haricots; par conséquent, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines, ce qui la rend adaptée aux personnes à qui l'on a conseillé de manger plus de protéines, en particulier celles sous dialyse. Si on vous a conseillé de réduire vos protéines, réduisez le poulet à 150 g ou optez pour l'option végétarienne/végane."],["Sans gluten","Remplacez la sauce soja par une alternative sans gluten comme le tamari."],["Végétarien/Végane","Remplacez le poulet par une boîte de 400 g de pois chiches ou de haricots beurre égouttés."],["Option plus saine","Cette recette est faible en sel, malgré l'utilisation de sauce soja. Nous recommandons d'utiliser une variété à teneur réduite en sel; elle reste cependant riche en sel, veillez donc à respecter la quantité indiquée."],["Conservation","Ce plat se déguste de préférence fraîchement préparé."],["Astuces","Si vous utilisez des edamames, vous pouvez les acheter surgelés. Faites-les d'abord décongeler au réfrigérateur."]],
[]),
(3802558,"Pomme au four",
"Cette recette de pomme au four offre un dessert fruité gourmand et délicieux, faible en potassium et en phosphate.",
"4",None,
["4 pommes à dessert (par exemple Gala, Braeburn, Pink Lady, Cox, Golden Delicious)","50 g de beurre non salé, ramolli","80 à 100 g de bleuets (frais ou surgelés et décongelés)","15 g de cassonade claire molle"],
["Chauffez le four à 180 °C / 160 °C / thermostat gaz 4. À l'aide d'un vide-pomme, évidez les pommes et agrandissez légèrement l'ouverture pour la garniture.","Mélangez le beurre ramolli, les bleuets et le sucre jusqu'à ce que le tout soit combiné, puis farcissez-en les quatre cavités des pommes.","Mettez les pommes dans un petit plat à rôtir et ajoutez 4 cuillères à soupe d'eau dans le plat.","Faites cuire 25 à 30 minutes, selon la taille des pommes, jusqu'à ce qu'elles soient tendres et caramélisées. Servez avec un filet de crème épaisse ou de la crème glacée à la vanille de soja."],
[["Note du chef","Ce dessert de pomme au four est délicieux après votre rôti du dimanche."],["Glucides","Les principales sources de glucides de ce plat sont les pommes et le sucre. Les valeurs en glucides sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","En respectant les quantités indiquées, ce dessert est faible en potassium et en phosphate; vous pouvez donc le savourer comme gâterie spéciale lorsque vous suivez des restrictions alimentaires."],["Protéines","Ce dessert est faible en protéines et peut donc être savouré comme gâterie occasionnelle si vous suivez un régime pauvre en protéines."],["Végane","Utilisez du beurre végane et de la crème épaisse végane ou de la crème glacée de soja."],["Option plus saine","Cette recette est riche en matières grasses, fournies par le beurre et la crème. Pour réduire les matières grasses, remplacez le beurre par une tartinade allégée ou utilisez moins de beurre (par exemple, la moitié de la quantité). Vous pourriez aussi remplacer la crème par de la crème fraîche demi-grasse ou un yogourt de soja nature."],["Conservation","Cette recette se déguste de préférence fraîche."],["Astuces","Les pommes peuvent être préparées la veille. Il suffit de les couvrir et de les réfrigérer jusqu'au moment de les cuire."]],
[]),
(3815833,"Lasagne au poulet et aux légumes",
"Cette recette est une excellente source de protéines et regorge de bienfaits supplémentaires grâce aux légumes.",
"4",None,
["300 g de filets de hauts de cuisse de poulet sans peau et désossés, coupés en dés","2 petits oignons ou 1 gros, pelés et finement hachés","4 gousses d'ail, pelées et écrasées","1 boîte de 400 g de tomates concassées","2 cuillères à café d'origan séché","9 feuilles de lasagne sèches","1 cuillère à soupe d'huile d'olive","100 g de carottes, pelées et coupées en petits dés","100 g d'épinards",["Sauce blanche","20 g de fécule de maïs"],["Sauce blanche","25 g de beurre non salé"],["Sauce blanche","150 ml de bouillon de poulet préparé avec ¼ de cube de bouillon de poulet sans sel"],["Sauce blanche","300 ml de lait"],["Sauce blanche","Poivre noir moulu"],["Sauce blanche","2 cuillères à café de muscade moulue"],["Sauce blanche","40 g de mozzarella râpée"],["Vinaigrette","1 cuillère à soupe d'huile d'olive"],["Vinaigrette","2 cuillères à café de vinaigre"],["Vinaigrette","2 cuillères à café de moutarde de Dijon"],["Vinaigrette","Poivre noir moulu"],["Pour servir","200 g de feuilles de salade mélangées"]],
["Préparez la sauce blanche en faisant fondre le beurre dans une petite casserole à feu moyen, puis incorporez la fécule de maïs et la muscade au fouet, en faisant cuire 2 minutes. Ajoutez lentement le lait et le bouillon de poulet en fouettant continuellement pour éviter les grumeaux. Gardez à feu moyen jusqu'à ce que la sauce ait épaissi. Retirez du feu et mettez de côté.","Faites chauffer la moitié de l'huile d'olive dans une poêle à feu moyen-vif et faites cuire le poulet jusqu'à ce qu'il soit doré de tous les côtés. Retirez de la poêle et mettez de côté. Faites chauffer le reste de l'huile dans la poêle et faites cuire l'oignon et la carotte jusqu'à ce qu'ils soient tendres, en ajoutant l'ail et l'origan, et faites cuire encore 2 minutes. Mettez les feuilles d'épinards dans une autre casserole et versez un peu d'eau bouillante dessus. Laissez mijoter 1 minute, ou jusqu'à ce que tous les épinards soient flétris, puis retirez du feu. Égouttez les épinards dans une passoire, puis rincez-les à l'eau froide et pressez-les pour éliminer l'excès d'eau. Ajoutez les tomates, les épinards et le poulet dans la poêle avec les carottes et l'oignon, portez à frémissement et faites cuire 5 minutes.","Chauffez le four à 180 °C / thermostat gaz 6. Étalez un tiers de la sauce blanche au fond d'un plat de cuisson, puis la moitié du mélange de poulet. Placez 4 ½ feuilles de lasagne, puis un autre tiers de la sauce blanche et le reste du mélange de poulet. Ajoutez ensuite le reste des feuilles de lasagne et terminez avec la sauce blanche. Saupoudrez de mozzarella. Faites cuire 40 minutes.","Préparez la vinaigrette en mettant tous les ingrédients dans un bol et en fouettant.","Sortez la lasagne du four et servez avec la salade mélangée et la vinaigrette."],
[["Note du chef","Une version santé d'une lasagne classique, cette délicieuse recette est parfaite pour toute la famille."],["Conseils sur la taille des portions pour les enfants","Les portions sont basées sur des portions d'adulte. Voici un guide pour les enfants :\nTout-petit (1 à 4 ans) : ¼ de portion d'adulte\nJeune enfant (5 à 9 ans) : ½ portion d'adulte\nEnfant plus âgé (10 à 13 ans) : ¾ de portion d'adulte\nAdolescents (14 ans et plus) : 1 portion d'adulte\nCertains enfants ont un appétit plus grand que d'autres. La portion de votre enfant pourrait devoir être adaptée à son alimentation habituelle si vous pensez que les portions recommandées sont trop grandes ou trop petites. Nous vous conseillons d'en parler avec votre diététiste avant d'augmenter la portion si votre enfant a de la difficulté à maîtriser son potassium ou son phosphate."],["Glucides","Les feuilles de lasagne sont la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré l'utilisation de certains ingrédients riches en potassium, comme les épinards et les tomates, cette recette est faible en potassium si l'on respecte les quantités des ingrédients, le mode de cuisson et les tailles de portion. Elle convient donc aux personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation.\nCette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par le poulet, le lait et le fromage; par conséquent, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué. Pour réduire davantage le phosphate, vous pourriez envisager de réduire la quantité de fromage dans la recette."],["Protéines","Cette recette est riche en protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse. Si on vous a conseillé de manger moins de protéines, vous pourriez réduire la quantité de poulet à 150 g et essayer d'ajouter plus de légumes comme des courgettes, des carottes et du brocoli."],["Énergie","Si vous devez prendre du poids, si vous avez un enfant en croissance qui a besoin de plus de calories ou si vous avez peu d'appétit, vous pouvez ajouter plus de beurre pour préparer la sauce blanche ou utiliser du lait entier pour augmenter les calories."],["Sans gluten","Utilisez des lasagnes sans gluten"],["Végétarien","Envisagez d'utiliser 300 à 400 g de tofu ou de viande de soja pour remplacer le poulet pour une option végétarienne."],["Végane","Envisagez d'utiliser des alternatives sans produits laitiers pour le beurre, le lait et le fromage."],["Option plus saine","Envisagez d'utiliser des feuilles de lasagne de blé entier pour une option plus saine."],["Option plus économique","Cette recette a été conçue pour coûter le moins cher possible."],["Conservation","Une fois cuite et refroidie, cette recette peut être conservée au réfrigérateur et réchauffée le lendemain. Assurez-vous qu'elle est bien chaude lors du réchauffage."]],
[]),
(3817119,"Gruau de pommes cuit au four",
"Ce gruau de pommes cuit au four est une gâterie copieuse, faible en potassium, pour les occasions spéciales.",
"6",None,
["140 g de flocons d'avoine","1 cuillère à café de poudre à pâte","1 banane mûre","100 ml de lait (ou d'alternative sans produits laitiers)","1 gros œuf","2 cuillères à soupe de sirop d'agave (ou de sirop d'érable)","1 cuillère à café d'essence de vanille","2 cuillères à café de cannelle","1 pomme, tranchée",["Pour servir","60 g de yogourt nature"],["Pour servir","10 g de noix de coco desséchée, grillée"],["Facultatif","250 g de fruits cuits (sans sucre ajouté) comme des poires ou des pommes"],["Facultatif","ou 400 g de fruits en conserve (dans le jus, jetez le jus), comme des pêches ou des poires"]],
["Préchauffez le four à 180 °C / 160 °C chaleur tournante / thermostat gaz 4. Huilez légèrement un plat allant au four. Mettez les flocons d'avoine et la poudre à pâte dans un mélangeur et mixez jusqu'à ce qu'ils soient moulus.","Ajoutez la banane, le lait, l'œuf, une cuillère à soupe de sirop, l'essence de vanille et la cannelle dans le mélangeur et mixez jusqu'à consistance lisse et bien combinée. Versez dans le plat allant au four.","Mélangez les tranches de pomme avec la cuillère à soupe de sirop restante et disposez-les sur le dessus du plat. Faites cuire 25 minutes.","Sortez du four et laissez refroidir quelques instants. Répartissez en six portions avec une cuillérée de yogourt sur le dessus, un peu de noix de coco grillée et les fruits facultatifs si désiré."],
[["Note du chef","Cette recette est très rapide à préparer. Elle pourrait être un dessert ou même se manger au déjeuner lors d'une occasion spéciale."],["Glucides","Les flocons d'avoine et le sirop sont les principales sources de glucides de ce dessert, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Ce dessert est faible en potassium; il convient donc, lors d'occasions spéciales, aux personnes à qui l'on a conseillé de suivre un régime pauvre en potassium.\nCette recette est riche en phosphate, à cause de l'avoine et de la poudre à pâte. Si on vous a conseillé de suivre un régime pauvre en phosphate, il vaut peut-être mieux limiter la fréquence à laquelle vous préparez cette recette. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Cette recette est faible en protéines, ce qui la rend adaptée aux personnes à qui l'on a conseillé de manger moins de protéines."],["Sans gluten","Utilisez de l'avoine sans gluten."],["Option plus saine","Vous pourriez envisager d'utiliser un yogourt faible en gras ou allégé, ou une alternative végétale comme un yogourt d'avoine ou de soja. Vous pouvez aussi servir avec des fruits cuits, comme des pommes et des poires, ou des fruits en conserve comme des pêches et des poires, comme suggéré."],["Conservation","Se conserve jusqu'à trois jours au réfrigérateur et se réchauffe avant de servir."]],
[]),
]
